numbers = [1, 2, 3, 4, 5]
keys = ["name", "age", "city"]
values = ["Alice", 30, "New York"]
original_dict = {"a": 1, "b": 2, "c": 3}
data_tuples = [("apple", 5), ("banana", 3), ("cherry", 8), ("apple", 2)]
student_grades = {"Alice": 85, "Bob": 92, "Charlie": 78, "Diana": 85}

# 1. Numbers to squares:
squares_dict = {num: num**2 for num in numbers}

# 2. Parallel lists to dictionary:
person_dict = {keys[i]: values[i] for i in range(len(keys))}

# 3. Transform dictionary (uppercase keys, double values):
transformed_dict = {k.upper(): v * 2 for k, v in original_dict.items()}

# 4. Filtered dictionary from tuples (only quantities > 4):
filtered_inventory = {item: qty for item, qty in data_tuples if qty > 4}

# 5. Swap grades and students (handle duplicate grades):
grade_to_students = {}
for student, grade in student_grades.items():
    if grade not in grade_to_students:
        grade_to_students[grade] = []
    grade_to_students[grade].append(student)

